                                    <th style="padding: 12px 14px; text-align: left; color: #64748b; font-weight: 800; position: sticky; top: 0; background: #f8fafc; z-index: 25; box-shadow: 0 2px 4px rgba(15,23,42,0.04);">AVANCE 2025</th>
